import random
import json
import os
from datetime import datetime

class QuizGame:
    def __init__(self):
        self.questions = [
            {
                "question": "What is the output of 2 + 3?",
                "options": ["4", "5", "6", "7"],
                "answer": "5"
            },
            {
                "question": "Which language is used for web development?",
                "options": ["Python", "HTML", "C", "Java"],
                "answer": "HTML"
            },
            {
                "question": "Which keyword defines a function in Python?",
                "options": ["function", "def", "fun", "define"],
                "answer": "def"
            },
            {
                "question": "Which data type stores True or False?",
                "options": ["int", "str", "bool", "float"],
                "answer": "bool"
            },
            {
                "question": "Which symbol is used for comments in Python?",
                "options": ["//", "#", "/*", "--"],
                "answer": "#"
            },
            {
                "question": "What does CPU stand for?",
                "options": [
                    "Central Processing Unit",
                    "Computer Personal Unit",
                    "Central Program Unit",
                    "Control Processing User"
                ],
                "answer": "Central Processing Unit"
            },
            {
                "question": "Which method adds an item to a list?",
                "options": ["add()", "insert()", "append()", "push()"],
                "answer": "append()"
            },
            {
                "question": "Which symbol is used for multiplication?",
                "options": ["x", "*", "%", "#"],
                "answer": "*"
            },
            {
                "question": "Which collection does not allow duplicate values?",
                "options": ["List", "Tuple", "Set", "String"],
                "answer": "Set"
            },
            {
                "question": "What is 10 // 3 in Python?",
                "options": ["3", "3.33", "1", "0"],
                "answer": "3"
            }
        ]
        self.score = 0
        self.total = 0
        self.username = ""

    def clear_screen(self):
        os.system("cls" if os.name == "nt" else "clear")

    def get_name(self):
        while True:
            self.username = input("Enter your name: ").strip()
            if self.username:
                break
            print("Name cannot be empty.")

    def show_header(self):
        print("=" * 60)
        print("                 PYTHON QUIZ GAME")
        print("=" * 60)
        print(f"Player: {self.username}")
        print()

    def show_question(self, question, number):
        print(f"Question {number}")
        print("-" * 60)
        print(question["question"])
        print()
        for index, option in enumerate(question["options"], 1):
            print(f"{index}. {option}")
        print()

    def get_answer(self):
        while True:
            choice = input("Enter option number: ").strip()
            if choice.isdigit():
                number = int(choice)
                if 1 <= number <= 4:
                    return number
            print("Please enter a number from 1 to 4.")

    def play(self):
        questions = self.questions.copy()
        random.shuffle(questions)
        self.score = 0
        self.total = len(questions)

        for number, question in enumerate(questions, 1):
            self.clear_screen()
            self.show_header()
            self.show_question(question, number)
            answer_number = self.get_answer()
            selected = question["options"][answer_number - 1]

            if selected == question["answer"]:
                print("\nCorrect!")
                self.score += 1
            else:
                print(f"\nWrong! Correct answer: {question['answer']}")

            input("\nPress Enter to continue...")

    def calculate_percentage(self):
        if self.total == 0:
            return 0
        return (self.score / self.total) * 100

    def get_grade(self):
        percentage = self.calculate_percentage()
        if percentage == 100:
            return "A+"
        if percentage >= 80:
            return "A"
        if percentage >= 60:
            return "B"
        if percentage >= 40:
            return "C"
        return "D"

    def show_result(self):
        self.clear_screen()
        percentage = self.calculate_percentage()
        grade = self.get_grade()

        print("=" * 60)
        print("                    RESULT")
        print("=" * 60)
        print(f"Player       : {self.username}")
        print(f"Score        : {self.score}/{self.total}")
        print(f"Percentage   : {percentage:.2f}%")
        print(f"Grade        : {grade}")
        print("=" * 60)

        if percentage == 100:
            print("Excellent performance!")
        elif percentage >= 80:
            print("Great job!")
        elif percentage >= 60:
            print("Good work!")
        elif percentage >= 40:
            print("Keep practicing!")
        else:
            print("Practice more and try again!")

    def save_result(self):
        filename = "quiz_results.json"

        result = {
            "name": self.username,
            "score": self.score,
            "total": self.total,
            "percentage": round(self.calculate_percentage(), 2),
            "grade": self.get_grade(),
            "date": datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        }

        data = []

        if os.path.exists(filename):
            try:
                with open(filename, "r") as file:
                    data = json.load(file)
            except:
                data = []

        data.append(result)

        with open(filename, "w") as file:
            json.dump(data, file, indent=4)

    def show_history(self):
        self.clear_screen()
        filename = "quiz_results.json"

        print("=" * 60)
        print("                    HISTORY")
        print("=" * 60)

        if not os.path.exists(filename):
            print("No results found.")
            input("\nPress Enter to continue...")
            return

        try:
            with open(filename, "r") as file:
                data = json.load(file)
        except:
            print("Unable to read history.")
            input("\nPress Enter to continue...")
            return

        if not data:
            print("No results found.")
        else:
            for index, result in enumerate(data, 1):
                print(f"\nAttempt {index}")
                print(f"Name       : {result['name']}")
                print(f"Score      : {result['score']}/{result['total']}")
                print(f"Percentage : {result['percentage']}%")
                print(f"Grade      : {result['grade']}")
                print(f"Date       : {result['date']}")

        input("\nPress Enter to continue...")

    def menu(self):
        while True:
            self.clear_screen()
            print("=" * 60)
            print("                  PYTHON QUIZ GAME")
            print("=" * 60)
            print("1. Start Quiz")
            print("2. View History")
            print("3. Exit")
            print("=" * 60)

            choice = input("Enter your choice: ").strip()

            if choice == "1":
                self.play()
                self.show_result()
                self.save_result()
                input("\nPress Enter to return to menu...")
            elif choice == "2":
                self.show_history()
            elif choice == "3":
                self.clear_screen()
                print("Thank you for playing!")
                break
            else:
                print("Invalid choice.")
                input("Press Enter to continue...")

def main():
    game = QuizGame()
    game.get_name()
    game.menu()

if __name__ == "__main__":
    main()
