import random
import json
import os
class GuessGame:
    def __init__(self):
        self.player = ""
        self.score = 0
        self.attempts = 0
        self.history_file = "game_history.json"
    def welcome(self):
        print("=" * 45)
        print("          GUESS THE NUMBER GAME")
        print("=" * 45)
        self.player = input("Enter your name: ").strip()
        if not self.player:
            self.player = "Player"
        print("Welcome,", self.player)
    def choose_level(self):
        print("\nChoose difficulty")
        print("1. Easy   (1-50)")
        print("2. Medium (1-100)")
        print("3. Hard   (1-500)")
        while True:
            choice = input("Enter choice: ").strip()
            if choice == "1":
                return 50, 10
            if choice == "2":
                return 100, 7
            if choice == "3":
                return 500, 12
            print("Invalid choice. Try again.")
    def play_round(self):
        maximum, limit = self.choose_level()
        number = random.randint(1, maximum)
        self.attempts = 0
        print(f"\nGuess a number between 1 and {maximum}.")
        print(f"You have {limit} attempts.")
        while self.attempts < limit:
            value = input("Enter your guess: ").strip()
            if not value.isdigit():
                print("Enter a valid number.")
                continue
            guess = int(value)
            if guess < 1 or guess > maximum:
                print("Number is outside the range.")
                continue
            self.attempts += 1
            if guess == number:
                points = (limit - self.attempts + 1) * 10
                self.score += points
                print("Correct!")
                print("Attempts:", self.attempts)
                print("Points:", points)
                return True
            if guess < number:
                print("Too low!")
            else:
                print("Too high!")
            remaining = limit - self.attempts
            print("Attempts remaining:", remaining)
        print("Game over!")
        print("The number was:", number)
        return False
    def save_result(self, won):
        data = []
        if os.path.exists(self.history_file):
            try:
                with open(self.history_file, "r") as file:
                    data = json.load(file)
            except (json.JSONDecodeError, OSError):
                data = []
        result = {
            "player": self.player,
            "won": won,
            "attempts": self.attempts,
            "score": self.score
        }
        data.append(result)
        with open(self.history_file, "w") as file:
            json.dump(data, file, indent=4)
    def show_history(self):
        print("\n========== HISTORY ==========")
        if not os.path.exists(self.history_file):
            print("No history found.")
            return
        try:
            with open(self.history_file, "r") as file:
                data = json.load(file)
        except (json.JSONDecodeError, OSError):
            print("No valid history found.")
            return
        if not data:
            print("No games played yet.")
            return
        for index, item in enumerate(data, 1):
            status = "Won" if item["won"] else "Lost"
            print(f"{index}. {item['player']} | {status} | Score: {item['score']}")
    def run(self):
        self.welcome()
        while True:
            print("\n1. Play Game")
            print("2. History")
            print("3. Exit")
            choice = input("Enter choice: ").strip()
            if choice == "1":
                won = self.play_round()
                self.save_result(won)
                print("Total score:", self.score)
            elif choice == "2":
                self.show_history()
            elif choice == "3":
                print("Thanks for playing!")
                break
            else:
                print("Invalid choice.")
def main():
    game = GuessGame()
    game.run()
if __name__ == "__main__":
    main()
